package io.baozhu.copilot.ai; import com.fasterxml.jackson.databind.*; import io.baozhu.copilot.api.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component; import java.net.URI; import java.net.http.*; import java.util.*; @Component @ConditionalOnProperty(name="ai.provider",havingValue="openai") public class OpenAiCompatibleProvider implements AiProvider { private final ObjectMapper mapper; private final HttpClient client=HttpClient.newHttpClient(); private final String baseUrl,key,model; public OpenAiCompatibleProvider(ObjectMapper m,@Value("${ai.base-url}")String b,@Value("${ai.api-key}")String k,@Value("${ai.model}")String model){mapper=m;baseUrl=b;key=k;this.model=model;} public String name(){return "openai";} public List<RuleSuggestion> suggestRules(String table,List<ColumnSpec> cols,List<Map<String,Object>> rows,String d){if(key==null||key.isBlank())throw new IllegalStateException("AI_API_KEY is required when AI_PROVIDER=openai"); try{String input=mapper.writeValueAsString(Map.of("table",table,"columns",cols,"samples",rows==null?List.of():rows,"description",d==null?"":d)); String prompt="Return only a JSON array of objects with ruleType, expression, rationale, severity, confidence. Suggest data quality rules for: "+input; String body=mapper.writeValueAsString(Map.of("model",model,"temperature",.1,"messages",List.of(Map.of("role","system","content","You are a data quality engineer."),Map.of("role","user","content",prompt)))); HttpRequest q=HttpRequest.newBuilder(URI.create(baseUrl+"/chat/completions")).header("Authorization","Bearer "+key).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build(); JsonNode root=mapper.readTree(client.send(q,HttpResponse.BodyHandlers.ofString()).body()); String content=root.at("/choices/0/message/content").asText().replace("```json","").replace("```",""); return mapper.readerForListOf(RuleSuggestion.class).readValue(content);}catch(Exception e){throw new IllegalStateException("AI provider request failed: "+e.getMessage(),e);} } }